// Package server is the tifa runtime. Only code generated by the tifa CLI should import it, so it
// exports only what that code uses: App, Hooks, Layout, Route, Main, DevMain, Input, Output,
// InputOutput and SessionOf. The server itself is unexported.
package server

import (
	"bufio"
	"context"
	"crypto/tls"

	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"runtime/debug"
	"slices"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/klauspost/compress/gzhttp"
	"github.com/liustack/tifa"
	"github.com/liustack/tifa/internal/config"
	"github.com/liustack/tifa/internal/core"
)

// Hooks are the optional functions of the application's hooks.go.
type Hooks struct {
	OnStart    func(ctx context.Context) error
	OnShutdown func(ctx context.Context) error
	OnRequest  func(c *tifa.Ctx, next func(*tifa.Ctx) error) error
	OnError    func(c *tifa.Ctx, err error) tifa.Error
}

type server struct {
	cfg    config.Server
	hooks  Hooks
	root   http.Handler // what the listener serves: s wrapped by tifa.SetHTTPHandler, set by Run
	mux    *http.ServeMux
	routes map[string]map[string]func(*tifa.Ctx) error // path, then method
	pages  map[string]bool                             // paths whose GET renders a page
	// pageCache holds the whole-page cache time of the pages that have one, by path.
	pageCache map[string]time.Duration
	// pageQuery holds the query parameters the Loads of a page read, by path: the whole-page
	// cache keeps them even when cache.ignore_query names them.
	pageQuery map[string][]string
	ignore    queryFilter
	// modules holds, by the path of a page, the IDs of its Layouts and route, outermost first,
	// and by the ID of a Layout, the IDs of the Layouts from the root down to it.
	modules map[string][]string
	// layouts holds the Loads of each Layout's chain by its ID, for a URL that matches no page
	// and shows its 404 inside that Layout. candidates are what notFoundAt picks that Layout from.
	layouts    map[string]layoutChain
	candidates []candidate

	// The front end, nil until openFront or setFront. Renders hold rendering for reading, so
	// swapFront can wait for those on the pool it replaces.
	front     atomic.Pointer[front]
	rendering sync.RWMutex
	cache     *htmlCache
	// dev answers the requests of tifa dev under /__tifa/dev/, set only by DevMain for an app with
	// pages.
	dev http.Handler
	// devErrors keeps the errors tifa dev asks for at deverrors.Path, set only by DevMain, also for
	// an app without pages.
	devErrors *devErrors
	// handler is route, wrapped by compressed when server.compress is on.
	handler http.Handler
	// crossSite refuses the writes a browser sends from another site, before anything else
	// sees the request, see refuseCrossSite.
	crossSite *http.CrossOriginProtection
	sess      sessionState
}

// newServer builds a server without routes. The ServeMux holds only the application's routes, so a
// root catch-all page (Path "/{rest...}") can be registered. ServeHTTP handles unmatched URLs.
func newServer(cfg config.Config, hooks Hooks) *server {
	s := &server{
		cfg: cfg.Server, hooks: hooks, mux: http.NewServeMux(),
		routes: map[string]map[string]func(*tifa.Ctx) error{}, pages: map[string]bool{}, pageCache: map[string]time.Duration{}, pageQuery: map[string][]string{}, ignore: newQueryFilter(cfg.Cache.IgnoreQuery),
		modules: map[string][]string{}, layouts: map[string]layoutChain{}, cache: newHTMLCache(cfg.Cache.Size),
	}
	s.crossSite = crossSiteProtection(cfg.Server)
	s.sess.cfg = cfg.Session
	s.handler = http.HandlerFunc(s.route)
	if cfg.Server.Compress {
		s.handler = compressed(s.handler)
	}
	return s
}

var methods = []string{"GET", "POST", "PUT", "PATCH", "DELETE"}

// handle registers a method handler of a route. The path is registered once without a method,
// so OnRequest runs with the matched pattern even when the method has no handler.
// Like http.ServeMux, it panics on invalid or conflicting registrations.
func (s *server) handle(method, path string, h func(*tifa.Ctx) error) {
	if !slices.Contains(methods, method) {
		panic(fmt.Sprintf("tifa: unsupported method %q for %s", method, path))
	}
	route := s.path(path)
	if route[method] != nil {
		panic(fmt.Sprintf("tifa: %s %s registered twice", method, path))
	}
	route[method] = h
}

// path registers path in the ServeMux on first use and returns its handlers by method.
func (s *server) path(path string) map[string]func(*tifa.Ctx) error {
	route, ok := s.routes[path]
	if !ok {
		route = map[string]func(*tifa.Ctx) error{}
		s.routes[path] = route
		pattern := path
		if path == "/" {
			pattern = "/{$}" // Path "/" is the exact home page, "/" in ServeMux would match every URL
		}
		s.mux.Handle(pattern, routeHandler{s: s, pattern: path, methods: route})
	}
	return route
}

// routeHandler is what the server registers in its ServeMux. methods is nil for unmatched URLs,
// which unmatched answers.
type routeHandler struct {
	s       *server
	pattern string
	methods map[string]func(*tifa.Ctx) error
}

func (h routeHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	h.s.serve(w, r, h.pattern, h.methods == nil || h.s.pages[h.pattern], func(c *tifa.Ctx) error {
		if h.methods == nil {
			return h.s.unmatched(c)
		}
		handle := h.methods[r.Method]
		if handle == nil && r.Method == "HEAD" {
			handle = h.methods["GET"]
		}
		if handle == nil {
			methodNotAllowed(c.Writer(), h.methods)
			return nil
		}
		// A page sends the build it was rendered with along with its calls. Other clients do not.
		if build := c.Header(buildHeader); build != "" && c.Header(callHeader) != "" && h.s.pagesServed() && build != h.s.front.Load().build.ID {
			return h.s.buildChanged(c)
		}
		return recovered(func() error { return handle(c) })
	})
}

func (s *server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	s.handler.ServeHTTP(w, r)
}

// route answers a request of tifa dev, a static file, or a request for a route.
func (s *server) route(w http.ResponseWriter, r *http.Request) {
	setDefaultHeaders(w.Header())
	if err := s.crossSite.Check(r); err != nil {
		s.refuseCrossSite(w, r, err)
		return
	}
	if s.serveDev(w, r) || s.serveStatic(w, r) {
		return
	}
	r = core.SplitData(r)
	if s.sess.enabled && r.URL.Path == sessionPath {
		s.serve(w, r, sessionPath, false, s.sessionHandler)
		return
	}
	h, _ := s.mux.Handler(r)
	if _, ok := h.(routeHandler); ok {
		s.mux.ServeHTTP(w, r)
		return
	}
	// ServeMux answers the other requests with its own handler: a redirect for a non-canonical path (double
	// slash, dot segment, missing trailing slash), or its 404 when no route matches. A redirect reaches
	// OnRequest as the result of Next. Anything else is an unmatched URL. ServeMux writes 307, a
	// temporary redirect, but the path is only another spelling of the page, so it goes out as 308,
	// the permanent one that keeps the method and that search engines take as the canonical URL.
	probe := &redirectProbe{header: http.Header{}}
	h.ServeHTTP(probe, r)
	location := probe.header.Get("Location")
	switch probe.code {
	case http.StatusMovedPermanently, http.StatusFound, http.StatusTemporaryRedirect, http.StatusPermanentRedirect:
		if location != "" {
			redirect := &core.RedirectError{URL: location, Status: http.StatusPermanentRedirect}
			s.serve(w, r, "", false, func(*tifa.Ctx) error { return redirect })
			return
		}
	}
	routeHandler{s: s}.ServeHTTP(w, r)
}

// redirectProbe captures the status and headers of a ServeMux internal handler and drops its body.
type redirectProbe struct {
	header http.Header
	code   int
}

func (p *redirectProbe) Header() http.Header         { return p.header }
func (p *redirectProbe) WriteHeader(code int)        { p.code = code }
func (p *redirectProbe) Write(b []byte) (int, error) { return len(b), nil }

// redirectLocation is the Location http.Redirect writes for url: a relative URL resolved against
// the path of r, with its dot segments removed and its non-ASCII bytes escaped.
func redirectLocation(r *http.Request, url string, code int) string {
	probe := &redirectProbe{header: http.Header{}}
	http.Redirect(probe, r, url, code)
	return probe.header.Get("Location")
}

// serve runs one request: OnRequest around route, then the error flow. pattern is empty when no
// route matched. page reports whether a GET of this URL is answered with a page: the route is a
// page, or no route matched.
func (s *server) serve(w http.ResponseWriter, r *http.Request, pattern string, page bool, route func(*tifa.Ctx) error) {
	tw := &writer{ResponseWriter: w, plain: !s.cfg.Compress}
	// The same template as c.Pattern(), for a middleware of tifa.SetHTTPHandler that reads it from
	// the request it passed on. ServeMux sets its own spelling, such as /{$} for the home page.
	if pattern != "" {
		r.Pattern = pattern
		if d := core.DataOf(r); d != nil {
			d.Original.Pattern = pattern
		}
	}
	// A page with the whole-page cache answers every visitor alike: its GET and HEAD, and the
	// navigation data of it, are made anonymous before anything of the app sees them.
	anon := s.anonymousRequest(pattern, r)
	var anonErr error
	if anon {
		r, anonErr = s.anonymize(r)
	}
	c := core.New(tw, r, pattern, s.cfg.BodyLimit)
	tw.noStore = func() bool { return core.NoStore(c) }
	tw.data = func() bool { return core.DataOf(r) != nil }
	tw.session = pattern == sessionPath
	// The cookie of an HTML answer would be kept and sent to everyone. A navigation answer is for
	// one browser and may set one.
	tw.noCookies = anon && !c.IsData()
	if anon {
		core.SetAnonymous(c)
	}
	defer func() {
		if err := core.Finish(c); err != nil {
			core.Logger().WarnContext(r.Context(), "tifa: removing the multipart files failed", "method", r.Method, "path", r.URL.Path, "err", err)
		}
	}()
	// The session is read before OnRequest, so every hook, Load and handler sees it. A store
	// that fails is an unexpected error: carrying on as signed out would hide the fault. An
	// anonymous request has none to read.
	err := anonErr
	if !anon {
		err = core.AttachSession(c, s.sessionEnv())
	}
	if err != nil && errors.Is(err, context.Canceled) && r.Context().Err() != nil {
		err = errClientGone
	}
	switch {
	case err != nil:
	case s.hooks.OnRequest == nil:
		err = route(c)
	default:
		var called atomic.Bool
		var routed atomic.Pointer[tifa.Ctx]
		next := func(nc *tifa.Ctx) error {
			if !called.CompareAndSwap(false, true) {
				return errors.New("tifa: next called more than once")
			}
			routed.Store(nc)
			defer core.SetSessionPhase(nc, core.PhaseAfterNext)
			return route(nc)
		}
		err = recovered(func() error { return s.hooks.OnRequest(c, next) })
		// The error flow sees what the route saw: the Ctx that OnRequest gave to next.
		if rc := routed.Load(); rc != nil {
			c = rc
		}
	}
	if err != nil {
		page = page && s.pagesServed() && (r.Method == "GET" || r.Method == "HEAD") && !c.IsData()
		s.fail(c, tw, err, page)
	}
}

// fail turns the error OnRequest returned into a response. Redirects, ErrNotFound and
// tifa.Error are expected results and skip OnError. page answers with an HTML page instead of
// JSON. A failed Load that OnRequest returned unchanged keeps the results of every loaded
// route: a data request answers them by route, a page renders with them. A request whose client
// went away while it waited for a shared render (errClientGone) has its connection cut.
func (s *server) fail(c *tifa.Ctx, w *writer, err error, page bool) {
	if errors.Is(err, errClientGone) {
		// Nothing has been written. Returning would let net/http send an empty 200 with the
		// page's ETag, which a browser or a CDN could keep, as the client may still be there
		// (it only half-closed, or middleware canceled the context). ErrAbortHandler cuts the
		// connection, or resets the stream over HTTP/2, without a log line. OnRequest has
		// returned, so recovered does not see it, and it passes recovered anyway.
		panic(http.ErrAbortHandler)
	}
	r := c.Request()
	var failure *loadFailure
	var missing *notFoundPage
	var failed *renderError
	var items map[string]routeResult
	var redirect *core.RedirectError
	var e tifa.Error
	errors.As(err, &missing)
	errors.As(err, &failed)
	if errors.As(err, &failure) {
		items, redirect, e = s.results(c, failure)
	} else {
		redirect, e = s.classify(c, err)
	}
	if c.Pattern() == sessionPath {
		// Whatever failed, the answer about the session is never stored.
		h := w.Header()
		h.Del("ETag")
		h.Del("Last-Modified")
		h.Set("Cache-Control", "private, no-store")
	}
	var shared *sessionCacheError
	if errors.As(err, &shared) {
		// Whatever OnError set, the answer to this error is never stored.
		h := w.Header()
		h.Del("ETag")
		h.Del("Last-Modified")
		h.Set("Cache-Control", "no-store")
	}
	if w.wrote {
		core.Logger().ErrorContext(r.Context(), "tifa: request failed after the response was written", "method", r.Method, "path", r.URL.Path, "err", err)
		return
	}
	// Only the collector sends _tifa. It also reaches a redirect of ServeMux, which has no
	// pattern.
	data := c.IsData() && s.pagesServed() && (r.Method == "GET" || r.Method == "HEAD")
	switch {
	case failure != nil && failure.data:
		_ = s.writeData(c, http.StatusOK, items)
	case missing != nil && missing.data && data:
		_ = s.writeData(c, http.StatusNotFound, missing.items)
	case redirect != nil && data:
		session := s.answerSession(c)
		if session != nil {
			s.sealSessionAnswer(c)
		}
		_ = writeDataBody(w, http.StatusOK, dataRedirect{Redirect: redirect.URL, Status: redirect.Status, Session: session})
	case redirect != nil && r.Header.Get(callHeader) != "":
		// The app's caching headers would let a cache hand this JSON to a page load.
		w.Header().Set("Cache-Control", "no-store")
		w.Header().Set(redirectHeader, strconv.Itoa(redirect.Status))
		w.Header().Add("Vary", callHeader)
		writeJSON(w, http.StatusOK, dataRedirect{Redirect: redirect.URL, Status: redirect.Status, Session: s.callSession(c)})
	case redirect != nil:
		w.Header().Add("Vary", callHeader)
		http.Redirect(w, r, redirect.URL, redirect.Status)
	case !page:
		body := errorBody{Error: e.Message}
		body.Fields, _ = fieldsOf(err)
		writeJSON(w, e.Status, body)
	case failed != nil:
		s.rescue(c, e, err, failed)
	case failure != nil:
		s.errorPage(c, e, err, items, failure.loads, failure.ssr, failure.key)
	case missing != nil:
		s.errorPage(c, e, err, missing.items, missing.loads, missing.ssr, missing.layout)
	default:
		s.errorPage(c, e, err, nil, time.Time{}, false, "")
	}
}

// classify sorts an error into a redirect or the public error to answer. Unexpected errors go
// to OnError. The URL of a redirect is resolved the way http.Redirect resolves it, so the JSON
// answers that carry it name the same URL a 3xx would.
func (s *server) classify(c *tifa.Ctx, err error) (*core.RedirectError, tifa.Error) {
	var redirect *core.RedirectError
	var e tifa.Error
	switch {
	case errors.As(err, &redirect):
		return &core.RedirectError{URL: redirectLocation(c.Request(), redirect.URL, redirect.Status), Status: redirect.Status}, e
	case errors.Is(err, tifa.ErrSSRBusy):
		c.SetHeader("Retry-After", "1")
		c.SetHeader("Cache-Control", "no-store")
		c.Writer().Header().Del("ETag")
		e = tifa.Error{Status: http.StatusServiceUnavailable, Message: http.StatusText(http.StatusServiceUnavailable)}
	case errors.Is(err, tifa.ErrNotFound):
		e = tifa.Error{Status: http.StatusNotFound, Message: http.StatusText(http.StatusNotFound)}
	case isFields(err):
		e = tifa.Error{Status: http.StatusUnprocessableEntity, Message: http.StatusText(http.StatusUnprocessableEntity)}
	case asPublic(err, &e):
		if e.Message == "" {
			e.Message = http.StatusText(e.Status)
		}
	default:
		e = s.publicError(c, err)
	}
	return nil, e
}

// publicError asks OnError what to show for an unexpected error. Without OnError it logs the error and answers 500.
// Under tifa dev it also notes the error for `tifa errors`.
func (s *server) publicError(c *tifa.Ctx, err error) tifa.Error {
	e := s.askOnError(c, err)
	s.devRequestError(c, e, err)
	return e
}

func (s *server) askOnError(c *tifa.Ctx, err error) tifa.Error {
	if s.hooks.OnError == nil {
		core.Logger().ErrorContext(c.Context(), "tifa: request failed", "method", c.Request().Method, "path", c.Request().URL.Path, "err", err)
		return tifa.Error{Status: http.StatusInternalServerError, Message: http.StatusText(http.StatusInternalServerError)}
	}
	core.SetSessionPhase(c, core.PhaseError)
	e := s.hooks.OnError(c, err)
	if !validStatus(e.Status) {
		e.Status = http.StatusInternalServerError
	}
	if e.Message == "" {
		e.Message = http.StatusText(e.Status)
	}
	return e
}

// asPublic finds a tifa.Error in err, as a value or a pointer since both satisfy error.
func asPublic(err error, e *tifa.Error) bool {
	var p *tifa.Error
	switch {
	case errors.As(err, e):
	case errors.As(err, &p) && p != nil:
		*e = *p
	default:
		return false
	}
	return validStatus(e.Status)
}

// validStatus reports whether a tifa.Error status can be sent as an error response.
// A tifa.Error with any other status is a bug in the code that built it, so it is handled as unexpected.
func validStatus(status int) bool { return status >= 400 && status <= 599 }

func methodNotAllowed(w http.ResponseWriter, route map[string]func(*tifa.Ctx) error) {
	var allow []string
	for _, m := range methods {
		if route[m] != nil {
			allow = append(allow, m)
			if m == "GET" {
				allow = append(allow, "HEAD")
			}
		}
	}
	w.Header().Set("Allow", strings.Join(allow, ", "))
	writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": http.StatusText(http.StatusMethodNotAllowed)})
}

// recovered turns a panic into an error so it follows the same flow as returned errors.
func recovered(f func() error) (err error) {
	defer func() {
		if p := recover(); p != nil {
			if p == http.ErrAbortHandler {
				panic(p)
			}
			err = fmt.Errorf("tifa: panic: %v\n%s", p, debug.Stack())
		}
	}()
	return f()
}

// noStoreUnlessSet makes an error answer say no-store, unless the application set a
// Cache-Control before the error, which then stays.
func noStoreUnlessSet(h http.Header) {
	if len(h.Values("Cache-Control")) == 0 {
		h.Set("Cache-Control", "no-store")
	}
}

// writeJSON writes the JSON answers of the framework: the body of every error that is not a page,
// 405, the 503 of a server that is shutting down, and the redirect a handler call of the browser
// gets. They are all failures or moves, so none is kept (see noStoreUnlessSet).
func writeJSON(w http.ResponseWriter, status int, value any) {
	data, err := core.MarshalJSON(value)
	if err != nil {
		http.Error(w, "JSON encoding failed", 500)
		return
	}
	noStoreUnlessSet(w.Header())
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Content-Length", strconv.Itoa(len(data)))
	w.WriteHeader(status)
	_, _ = w.Write(data)
}

// defaultCacheControl is what an answer says when the application set no Cache-Control. It
// keeps a shared cache (a CDN, a proxy) from storing an answer that may be meant for one visitor,
// and still lets the browser keep it and ask again with its ETag, which ends in a 304.
const defaultCacheControl = "private, no-cache"

// writer records whether the response is committed, so a late error does not write a second response.
// Every call that can commit goes through commit, the one place that decides. It is also where an
// answer without a Cache-Control gets defaultCacheControl, once, as the final header goes out.
type writer struct {
	http.ResponseWriter
	wrote bool
	plain bool // server.compress is off: No-Gzip-Compression goes, as gzhttp removes it when it is on
	// noStore reports that the answer sets the session cookie or answers a failed session store: it
	// goes out as no-store, without validators.
	noStore func() bool
	// data reports a navigation data request, whose answer is for one visitor and is never
	// public: it goes out private, no-cache whatever the application set, unless that is
	// stricter (no-store, or private with no-cache).
	data func() bool
	// session is set for /__tifa/session: whatever wrote the answer, a middleware that answered on
	// its own included, it goes out as private, no-store, without validators.
	session bool
	// noCookies drops the Set-Cookie headers of the answer: it is the HTML of a page with the
	// whole-page cache, which every visitor gets.
	noCookies bool
}

// Committed reports whether the response is on its way out. SetSession asks it.
func (w *writer) Committed() bool { return w.wrote }

// commit runs call on the underlying writer. The response counts as committed only when call returns
// normally and reports that it committed. A panic leaves the state untouched and propagates.
// final is false for a 1xx header, which precedes the real response and does not fix its headers.
func (w *writer) commit(final bool, call func() bool) {
	if w.plain {
		w.Header().Del(gzhttp.HeaderNoCompression)
	}
	if final && !w.wrote {
		h := w.Header()
		if w.noCookies {
			h.Del("Set-Cookie")
		}
		switch {
		case w.session:
			h.Set("Cache-Control", "private, no-store")
			h.Del("ETag")
			h.Del("Last-Modified")
		case w.noStore != nil && w.noStore():
			// A cache must not keep or share an answer that sets or drops a session, and a
			// validator would let a browser turn the next one into a 304 without the cookie.
			h.Set("Cache-Control", "no-store")
			h.Del("ETag")
			h.Del("Last-Modified")
		case w.data != nil && w.data():
			if len(h.Values("Cache-Control")) == 0 || !cacheControlHoldsSession(h) {
				h.Set("Cache-Control", defaultCacheControl)
			}
		case len(h.Values("Cache-Control")) == 0:
			h.Set("Cache-Control", defaultCacheControl)
		}
	}
	if call() {
		w.wrote = true
	}
}

// WriteHeader commits on final statuses. Like net/http, 1xx other than 101 is informational and may
// precede the real response.
func (w *writer) WriteHeader(code int) {
	w.commit(code >= 200, func() bool {
		w.ResponseWriter.WriteHeader(code)
		return code < 100 || code > 199 || code == http.StatusSwitchingProtocols
	})
}

// Write commits once it succeeds, even with no bytes since that sends the header, or once any byte went out.
func (w *writer) Write(b []byte) (n int, err error) {
	w.commit(true, func() bool {
		n, err = w.ResponseWriter.Write(b)
		return err == nil || n > 0
	})
	return n, err
}

// WriteString hands s on whole to a writer that takes strings, as net/http's does, so a page
// is not copied into a byte slice on the way.
func (w *writer) WriteString(s string) (n int, err error) {
	w.commit(true, func() bool {
		n, err = io.WriteString(w.ResponseWriter, s)
		return err == nil || n > 0
	})
	return n, err
}

// Of the operations http.ResponseController reaches, Flush and Hijack commit the response, so the writer
// implements them itself. Deadlines and full duplex do not commit and go through Unwrap.
func (w *writer) Unwrap() http.ResponseWriter { return w.ResponseWriter }

func (w *writer) FlushError() (err error) {
	w.commit(true, func() bool {
		err = http.NewResponseController(w.ResponseWriter).Flush()
		return err == nil
	})
	return err
}

func (w *writer) Flush() { _ = w.FlushError() }

func (w *writer) Hijack() (conn net.Conn, rw *bufio.ReadWriter, err error) {
	w.commit(false, func() bool {
		conn, rw, err = http.NewResponseController(w.ResponseWriter).Hijack()
		return err == nil
	})
	return conn, rw, err
}

// run calls OnStart with ctx, listens on the configured addresses and serves until ctx is done. With
// HTTPS on, server.addr serves HTTPS and server.http_addr, unless it is off, plain HTTP that
// answers the challenges of the ACME server and redirects the rest to HTTPS.
func (s *server) run(ctx context.Context) error {
	if err := checkServeMux(); err != nil {
		return err
	}
	// The sockets of systemd socket activation, which systemd keeps open while the program
	// restarts: the connections that arrive meanwhile wait for the next one. They are read
	// first, since a socket for server.addr is listened on in place of the address, which HTTPS
	// then does not need set.
	sockets, err := takeSystemdSockets()
	if err != nil {
		return err
	}
	defer closeAll(sockets) // those still here when run fails before it listens
	if sockets[socketAddr] == nil {
		if err := s.cfg.CheckHTTPSAddr(); err != nil {
			return err
		}
	}
	tlsConfig, plain, ready, err := s.https()
	if err != nil {
		return err
	}
	plainHTTP := tlsConfig != nil && s.cfg.HTTPAddr != "off"
	if err := unusedSocket(sockets, plainHTTP); err != nil {
		return err
	}
	if s.hooks.OnStart != nil {
		if err := s.hooks.OnStart(ctx); err != nil {
			return fmt.Errorf("tifa: OnStart: %w", err)
		}
	}
	// After OnStart, which is where an app calls tifa.SetHTTPHandler and tifa.SetSessionStore.
	root, release := core.SealHTTPHandler(s)
	defer release()
	s.root = root
	defer s.startSessions()()
	ln, fromSystemd, err := listen(sockets, socketAddr, s.cfg.Addr)
	if err != nil {
		return err
	}
	var plainLn net.Listener
	plainFromSystemd := false
	if plainHTTP {
		if plainLn, plainFromSystemd, err = listen(sockets, socketHTTPAddr, s.cfg.HTTPAddr); err != nil {
			ln.Close()
			return err
		}
	}
	// Under DevMain the app listens on an address only tifa dev talks to, and tifa dev prints
	// the one to open.
	if s.dev == nil {
		scheme := "http"
		if tlsConfig != nil {
			scheme = "https"
		}
		core.Logger().Info("tifa: listening on "+scheme+"://"+ln.Addr().String(), socketFrom(fromSystemd)...)
		if tlsConfig != nil {
			warnLoopback(ln.Addr())
		}
		if plainLn != nil {
			core.Logger().Info("tifa: listening on http://"+plainLn.Addr().String(), append([]any{"redirects_to", "https"}, socketFrom(plainFromSystemd)...)...)
		}
	}
	ready()
	return s.serveBoth(ctx, ln, tlsConfig, plainLn, plain)
}

// checkServeMux fails when ServeMux runs the Go 1.21 semantics, which GODEBUG=httpmuxgo121=1 selects
// from the environment, a godebug line in go.mod or a //go:debug directive. Paths would then be
// literal strings and {name} would never match. net/http reads the setting once at startup, so a
// probe registration shows what this process does, whatever the source of the setting.
func checkServeMux() error {
	mux := http.NewServeMux()
	mux.Handle("/{probe}", http.NotFoundHandler())
	if _, pattern := mux.Handler(&http.Request{Method: "GET", URL: &url.URL{Path: "/x"}}); pattern != "/{probe}" {
		return errors.New("tifa: ServeMux runs the Go 1.21 pattern semantics (GODEBUG httpmuxgo121=1), remove that setting")
	}
	return nil
}

// testHookEntry lets tests pause a request between net/http handing it over and the gate admitting it.
var testHookEntry func(stage string)

// testHookServer lets tests see each http.Server that serveBoth starts.
var testHookServer func(*http.Server)

// gate is the one boundary between net/http and handler code. Admitting a request and closing the gate
// take the same lock, so once close returns no handler code can start, and every handler that did start
// is counted before anyone waits.
type gate struct {
	mu      sync.Mutex
	closed  bool
	running sync.WaitGroup
}

func (g *gate) enter() bool {
	g.mu.Lock()
	defer g.mu.Unlock()
	if g.closed {
		return false
	}
	g.running.Add(1)
	return true
}

func (g *gate) leave() { g.running.Done() }

func (g *gate) close() {
	g.mu.Lock()
	g.closed = true
	g.mu.Unlock()
}

// wait reports whether every admitted handler returned within timeout. Call it after close.
func (g *gate) wait(timeout time.Duration) bool {
	returned := make(chan struct{})
	go func() {
		g.running.Wait()
		close(returned)
	}()
	select {
	case <-returned:
		return true
	case <-time.After(timeout):
		return false
	}
}

// serveListener serves plain HTTP on ln until ctx is done or ln fails, then shuts down the same way in both cases:
//  1. close the channel of tifa.ShuttingDown, stop accepting and wait up to shutdown_timeout for connections to
//     finish, as http.Server.Shutdown does
//  2. close the gate, so a request net/http hands over from now on gets 503 without running handler code
//  3. cancel every request context and close the remaining connections, which also reaches hijacked ones
//  4. wait up to shutdown_timeout for admitted handlers to return
//  5. call OnShutdown with its own shutdown_timeout
//
// If a handler never returns, OnShutdown is skipped and serveListener reports it, because cleaning up under a
// running handler is worse than not cleaning up. serveListener always closes ln, also when it refuses to start.
func (s *server) serveListener(ctx context.Context, ln net.Listener) error {
	return s.serveBoth(ctx, ln, nil, nil, nil)
}

// serveBoth is Serve with HTTPS: ln serves TLS with tlsConfig when it is not nil, and plainLn,
// when not nil, serves plain on its own server. That server runs no handler code, so it only
// takes part in step 1: it stops accepting and finishes its requests alongside ln. A failure of
// either listener shuts both down.
func (s *server) serveBoth(ctx context.Context, ln net.Listener, tlsConfig *tls.Config, plainLn net.Listener, plain http.Handler) error {
	if err := checkServeMux(); err != nil {
		ln.Close()
		if plainLn != nil {
			plainLn.Close()
		}
		return err
	}
	var g gate
	var root http.Handler = s
	if s.root != nil {
		root = s.root
	}
	// stopping closes as the shutdown starts, which handlers read with tifa.ShuttingDown: a stream
	// with no end of its own returns then, instead of holding the stop for shutdown_timeout.
	stopping := make(chan struct{})
	base, cancelRequests := context.WithCancel(core.WithShutdown(context.Background(), stopping))
	defer cancelRequests()
	srv := s.httpServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if testHookEntry != nil {
			testHookEntry("before")
			defer testHookEntry("done")
		}
		if s.cfg.HSTS {
			w.Header().Set("Strict-Transport-Security", "max-age=31536000")
		}
		if !g.enter() {
			w.Header().Set("Connection", "close")
			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": http.StatusText(http.StatusServiceUnavailable)})
			return
		}
		defer g.leave()
		root.ServeHTTP(w, r)
	}))
	srv.BaseContext = func(net.Listener) context.Context { return base }
	// ServeTLS adds h2 and http/1.1 to NextProtos and turns HTTP/2 on.
	srv.TLSConfig = tlsConfig
	served := make(chan error, 2)
	go func() {
		if tlsConfig != nil {
			served <- srv.ServeTLS(ln, "", "")
		} else {
			served <- srv.Serve(ln)
		}
	}()
	running := 1
	var plainSrv *http.Server
	if plainLn != nil {
		plainSrv = s.httpServer(plain)
		go func() { served <- plainSrv.Serve(plainLn) }()
		running++
	}
	var serveErr error // the listener failure, nil when ctx ended serving
	select {
	case serveErr = <-served:
		serveErr = fmt.Errorf("tifa: serving stopped: %w", serveErr)
		running--
	case <-ctx.Done():
	}
	close(stopping)
	drain, cancel := context.WithTimeout(context.Background(), s.cfg.ShutdownTimeout)
	plainDone := make(chan error, 1)
	if plainSrv != nil {
		go func() { plainDone <- plainSrv.Shutdown(drain) }()
	} else {
		plainDone <- nil
	}
	err := srv.Shutdown(drain)
	if plainErr := <-plainDone; err == nil {
		err = plainErr
	}
	cancel()
	if err != nil {
		err = fmt.Errorf("tifa: waiting for in-flight requests: %w", err)
	}
	err = errors.Join(serveErr, err)
	g.close()
	cancelRequests()
	_ = srv.Close()
	if plainSrv != nil {
		_ = plainSrv.Close()
	}
	for ; running > 0; running-- {
		<-served // http.ErrServerClosed
	}
	if !g.wait(s.cfg.ShutdownTimeout) {
		return errors.Join(err, errors.New("tifa: handlers still running after shutdown, OnShutdown skipped"))
	}
	if s.hooks.OnShutdown != nil {
		hookCtx, cancel := context.WithTimeout(context.Background(), s.cfg.ShutdownTimeout)
		defer cancel()
		if hookErr := s.hooks.OnShutdown(hookCtx); hookErr != nil {
			err = errors.Join(err, fmt.Errorf("tifa: OnShutdown: %w", hookErr))
		}
	}
	return err
}

// httpServer is an http.Server for h with the limits of the settings, the one place they are
// written: the server of server.addr and the plain one of server.http_addr both read and write
// under server.read_timeout and server.write_timeout. A handler that needs longer, an upload or
// a stream, lifts them for itself with http.ResponseController, which reaches the connection
// through Unwrap.
func (s *server) httpServer(h http.Handler) *http.Server {
	srv := &http.Server{
		Handler:           h,
		ReadHeaderTimeout: 5 * time.Second, ReadTimeout: s.cfg.ReadTimeout, WriteTimeout: s.cfg.WriteTimeout, IdleTimeout: 60 * time.Second,
	}
	if testHookServer != nil {
		testHookServer(srv)
	}
	return srv
}

// errorBody is the JSON answer for a failed request that is not a page.
type errorBody struct {
	Error  string      `json:"error"`
	Fields tifa.Fields `json:"fields,omitempty"`
}
